,p_item_templ_curr_w_child=>'<li class="amc-TAccordionRail-item amc-TAccordionRail-item--group is-current"><a class="amc-TAccordionRail-link" href="#LINK#"><span class="amc-TAccordionRail-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TAccordionRail-label">#TEXT#</span><span class="amc-TAccordionRail-badge">#A01#</span></a><details class="amc-TAccordionRail-group" open><summary class="amc-TAccordionRail-toggle"><span class="amc-TAccordionRail-srOnly">#TEXT#</span></summary>'
,p_list_template_noncurrent=>'<li class="amc-TAccordionRail-item"><a class="amc-TAccordionRail-link" href="#LINK#"><span class="amc-TAccordionRail-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TAccordionRail-label">#TEXT#</span><span class="amc-TAccordionRail-badge">#A01#</span></a></li>'
,p_item_templ_noncurr_w_child=>'<li class="amc-TAccordionRail-item amc-TAccordionRail-item--group"><a class="amc-TAccordionRail-link" href="#LINK#"><span class="amc-TAccordionRail-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TAccordionRail-label">#TEXT#</span><span class="amc-TAccordionRail-badge">#A01#</span></a><details class="amc-TAccordionRail-group"><summary class="amc-TAccordionRail-toggle"><span class="amc-TAccordionRail-srOnly">#TEXT#</span></summary>'
,p_before_sub_list=>'<ul class="amc-TAccordionRail-sub">'
,p_after_sub_list=>'</ul></details></li>'
,p_sub_list_item_current=>'<li class="amc-TAccordionRail-subitem is-current"><a class="amc-TAccordionRail-sublink" href="#LINK#" aria-current="page"><span class="amc-TAccordionRail-label">#TEXT#</span><span class="amc-TAccordionRail-badge">#A01#</span></a></li>'
,p_sub_list_item_noncurrent=>'<li class="amc-TAccordionRail-subitem"><a class="amc-TAccordionRail-sublink" href="#LINK#"><span class="amc-TAccordionRail-label">#TEXT#</span><span class="amc-TAccordionRail-badge">#A01#</span></a></li>'
,p_list_template_name=>'AMC Accordion Rail'
,p_internal_name=>'AMC_TPL_ACCORDION_RAIL'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-accordion-rail.css'
,p_a01_label=>'Badge'
,p_list_template_comment=>'List template for side navigation with one level of sub lists. Every entry is a real link; the current entry gets aria-current=page, and a parent whose group holds the current page is shown on the current path. Entries with children render their link plus a native disclosure toggle, so groups open and close with the mouse, Enter or Space and without JavaScript; the current group starts open. In browsers that support ::details-content the group grows and shrinks smoothly. The rail lights up from the current parent down to the current page. Attribute 1 is a badge, hidden when empty. Template options: Icon rail clips the list to its icons and reveals it over the page on hover or keyboard focus, with a dot on icons that carry a badge; Compact tightens the rows; Panel puts the navigation on a card surface; Flowing light sends a light pulse along the lit rail. Under prefers-reduced-motion nothing animates; in forced-colors mode the rail and current entry use system colors.'
);
end;
/
