 p_id=>wwv_flow_imp.id(211322988954911356)
,p_list_template_before_rows=>'<ul class="amc-TClayMenu #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">'
,p_list_template_after_rows=>'</ul>'
,p_list_template_current=>'<li class="amc-TClayMenu-item is-current"><a class="amc-TClayMenu-pill" href="#LINK#" aria-current="page"><span class="amc-TClayMenu-bubble fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TClayMenu-label">#TEXT#</span><span class="amc-TClayMenu-badge">#A01#</span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TClayMenu-item"><a class="amc-TClayMenu-pill" href="#LINK#"><span class="amc-TClayMenu-bubble fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TClayMenu-label">#TEXT#</span><span class="amc-TClayMenu-badge">#A01#</span></a></li>'
,p_list_template_name=>'AMC Clay Menu'
,p_internal_name=>'AMC_TPL_CLAY_MENU'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-clay-menu.css'
,p_a01_label=>'Badge'
,p_list_template_comment=>'List template that shows entries as soft clay pills sitting on a tray. Each pill has a glossy icon bubble whose color rotates through the palette, and the current entry is pressed into the tray. Pills wrap onto more rows when space runs out. Use the Badge attribute (A01) for a short count shown in a small bubble. Template options: Vertical stacks full-width pills for side columns, Large makes pills taller for touch screens, Single color uses the primary color for every bubble, Icons only hides the labels visually (they stay available to screen readers, so give every entry an icon), and Fill row stretches pills to share the row. Keyboard focus shows a ring around the pill. Under reduced motion pills do not move; in forced-colors mode pills get system borders and the current entry a highlight border.'
);
end;
/
