prompt --application/shared_components/user_interface/templates/region/clay_panel
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(338166029690761263)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TClayPanel #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <header class="amc-TClayPanel-header">',
'    <span class="amc-TClayPanel-bubble fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'    <h2 class="amc-TClayPanel-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'    <div class="amc-TClayPanel-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'  </header>',
'  <div class="amc-TClayPanel-body">#BODY##SUB_REGIONS#</div>',
'  <footer class="amc-TClayPanel-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'</section>'))
,p_page_plug_template_name=>'AMC Clay Panel'
,p_internal_name=>'AMC_TPL_CLAY_PANEL'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-clay-panel.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template in claymorphism style. Its inner and outer shadows are mixed from the palette color and the page background, so the clay follows the theme and dark styles. The title sits in a raised pill and the region icon in a glossy bubble; the native region sits in a slightly pressed tray with a solid surface so reports and forms stay readable. Help, Edit, Change, Copy, Delete and Create buttons sit in the header, Previous, Close and Next in the footer. Template options tint the clay success, danger, warm or neutral, or remove the tray padding. On hover or focus the panel puffs up and the bubble squishes; under reduced motion nothing moves. In forced-colors mode the shadows are replaced by system borders.'
);
end;
/
