begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(892463289664171710)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TCommandList #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<div class="amc-TCommandList-search" hidden>',
'<span class="amc-TCommandList-searchIcon" aria-hidden="true"></span>',
'<input type="search" class="amc-TCommandList-input" placeholder="Type a command or search" aria-label="Filter commands" autocomplete="off" spellcheck="false">',
'<kbd class="amc-TCommandList-escKey" aria-hidden="true">Esc</kbd>',
'</div>',
'<ul class="amc-TCommandList-list">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'<p class="amc-TCommandList-empty" hidden>No matching commands</p>',
'<p class="amc-TCommandList-status" role="status" aria-live="polite" data-results="results"></p>',
'</div>'))
,p_list_template_current=>'<li class="amc-TCommandList-item is-current"><a class="amc-TCommandList-link" href="#LINK#" aria-current="page"><span class="amc-TCommandList-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TCommandList-text"><span class="amc-TCommandList-label">#TEXT#</span><span class="amc-TCommandList-desc">#A01#</span></span><kbd class="amc-TCommandList-kbd">#A02#</kbd><span class="amc-TCommandList-enter" aria-hidden="true"></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TCommandList-item"><a class="amc-TCommandList-link" href="#LINK#"><span class="amc-TCommandList-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TCommandList-text"><span class="amc-TCommandList-label">#TEXT#</span><span class="amc-TCommandList-desc">#A01#</span></span><kbd class="amc-TCommandList-kbd">#A02#</kbd><span class="amc-TCommandList-enter" aria-hidden="true"></span></a></li>'
,p_list_template_name=>'AMC Command List'
,p_internal_name=>'AMC_TPL_COMMAND_LIST'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-command-list.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-command-list.css'
,p_a01_label=>'Description'
,p_a02_label=>'Shortcut'
,p_list_template_comment=>'List template shaped like a command palette. The search box filters entries by their label and description as you type and highlights the matching text; Enter in the box opens the first match, Arrow Down moves into the list, Arrow Up and Arrow Down, Home and End move between visible commands, and Escape returns to the box or clears it. Use the Description attribute (A01) for a one-line explanation and the Shortcut attribute (A02) for a keyboard shortcut shown as a key chip, for example Ctrl+N (separate keys with a plus sign; the shortcut is only displayed, not bound). The layout adapts to its container: in narrow columns the shortcut chips hide and descriptions move under the label. Template options: Compact rows, Hide search keeps arrow-key navigation without the box, Elevated floats the palette on a shadow with a glowing edge, and Two columns splits commands into two columns in wide containers. Without JavaScript it is a plain list of links and the search box stays hidden. The placeholder, the no-match message and the result count words are English text in the template; translate them there if needed.'
);
end;
/
