,p_list_template_noncurrent=>'<li class="amc-TDockBar-item"><a class="amc-TDockBar-link" href="#LINK#"><span class="amc-TDockBar-tip"><span class="amc-TDockBar-label">#TEXT#</span></span><span class="amc-TDockBar-tile"><span class="amc-TDockBar-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TDockBar-badge">#A01#</span></span></a></li>'
