,p_list_template_current=>'<li class="amc-TFlipTiles-item is-current"><a class="amc-TFlipTiles-link" href="#LINK#" aria-current="page"><span class="amc-TFlipTiles-card"><span class="amc-TFlipTiles-face amc-TFlipTiles-front"><span class="amc-TFlipTiles-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TFlipTiles-label">#TEXT#</span><span class="amc-TFlipTiles-fold" aria-hidden="true"></span></span><span class="amc-TFlipTiles-face amc-TFlipTiles-back"><span class="amc-TFlipTiles-backTitle" aria-hidden="true">#TEXT#</span><span class="amc-TFlipTiles-desc">#A01#</span><span class="amc-TFlipTiles-cta"><span class="amc-TFlipTiles-ctaText">#A02#</span><span class="amc-TFlipTiles-arrow fa fa-arrow-right" aria-hidden="true"></span></span></span></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TFlipTiles-item"><a class="amc-TFlipTiles-link" href="#LINK#"><span class="amc-TFlipTiles-card"><span class="amc-TFlipTiles-face amc-TFlipTiles-front"><span class="amc-TFlipTiles-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TFlipTiles-label">#TEXT#</span><span class="amc-TFlipTiles-fold" aria-hidden="true"></span></span><span class="amc-TFlipTiles-face amc-TFlipTiles-back"><span class="amc-TFlipTiles-backTitle" aria-hidden="true">#TEXT#</span><span class="amc-TFlipTiles-desc">#A01#</span><span class="amc-TFlipTiles-cta"><span class="amc-TFlipTiles-ctaText">#A02#</span><span class="amc-TFlipTiles-arrow fa fa-arrow-right" aria-hidden="true"></span></span></span></span></a></li>'
,p_list_template_name=>'AMC Flip Tiles'
