prompt --application/shared_components/user_interface/templates/region/glass_depth
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(918993849993498668)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TGlassDepth #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <span class="amc-TGlassDepth-backdrop" aria-hidden="true"></span>',
'  <span class="amc-TGlassDepth-sheet" aria-hidden="true"></span>',
'  <div class="amc-TGlassDepth-panel">',
'    <span class="amc-TGlassDepth-glass" aria-hidden="true"></span>',
'    <header class="amc-TGlassDepth-header">',
'      <span class="amc-TGlassDepth-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TGlassDepth-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TGlassDepth-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'    </header>',
'    <div class="amc-TGlassDepth-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TGlassDepth-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'</section>'))
,p_page_plug_template_name=>'AMC Glass Depth'
,p_internal_name=>'AMC_TPL_GLASS_DEPTH'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-glass-depth.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template with a floating frosted-glass panel. The frame draws soft palette-colored light behind the panel; the panel blurs it, has a light top edge and a layered depth shadow, and a second glass sheet peeks out underneath. Title and icon sit on the glass; the body keeps an almost opaque surface so reports and forms stay readable. Help, Edit, Change, Copy, Delete and Create buttons sit in the header, Previous, Close and Next in the footer. Template options tint the light with the success, danger or warning palette colors, float the panel higher, or remove the body padding. The light drifts slowly and the panel lifts a little more on hover or focus; under reduced motion everything stays still. In forced-colors mode the glass is replaced by a plain system border.'
);
end;
/
