,p_list_template_noncurrent=>'<li class="amc-TLiquidTabs-item"><a class="amc-TLiquidTabs-link" href="#LINK#"><span class="amc-TLiquidTabs-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TLiquidTabs-label">#TEXT#</span><span class="amc-TLiquidTabs-badge">#A01#</span></a></li>'
