,p_list_template_noncurrent=>'<li class="amc-TMarqueeLinks-item"><a class="amc-TMarqueeLinks-link" href="#LINK#"><span class="amc-TMarqueeLinks-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMarqueeLinks-tag">#A01#</span><span class="amc-TMarqueeLinks-label">#TEXT#</span></a></li>'
,p_list_template_name=>'AMC Marquee Links'
