begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(968592827010183141)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TMetroSteps #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<ol class="amc-TMetroSteps-line">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ol>',
'</div>'))
,p_list_template_current=>'<li class="amc-TMetroSteps-station is-current"><a class="amc-TMetroSteps-link" href="#LINK#" aria-current="step"><span class="amc-TMetroSteps-marker" aria-hidden="true"><span class="amc-TMetroSteps-icon fa #ICON_CSS_CLASSES#"></span></span><span class="amc-TMetroSteps-text"><span class="amc-TMetroSteps-label">#TEXT#</span><span class="amc-TMetroSteps-caption">#A01#</span></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TMetroSteps-station"><a class="amc-TMetroSteps-link" href="#LINK#"><span class="amc-TMetroSteps-marker" aria-hidden="true"><span class="amc-TMetroSteps-icon fa #ICON_CSS_CLASSES#"></span></span><span class="amc-TMetroSteps-text"><span class="amc-TMetroSteps-label">#TEXT#</span><span class="amc-TMetroSteps-caption">#A01#</span></span></a></li>'
,p_list_template_name=>'AMC Metro Steps'
,p_internal_name=>'AMC_TPL_METRO_STEPS'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-metro-steps.css'
,p_a01_label=>'Caption'
,p_list_template_comment=>'List template for wizard progress and process steps, drawn as a metro line. The current list entry is the current station; every entry before it is shown as completed (solid line, check mark) and every entry after it as planned (dashed line, station number). The current station shows the entry icon, pulses gently and carries its label on a station sign. Use the Caption attribute (A01) for a short line under the label such as a date or owner. The line runs horizontally in wide regions and switches to a vertical line when the region is narrower than about 36rem. Template options: Vertical always draws the line vertically, Staggered labels alternates labels above and below a horizontal line for long names, Compact makes stations smaller and hides captions, Numbers only shows the step number instead of the icon on the current station, and Calm turns off the pulse. The current entry has aria-current set to step. Completed states rely on the CSS :has selector (all current browsers); without it earlier stations look planned. Under reduced motion nothing pulses; in forced-colors mode stations and lines use system colors.'
);
end;
/
