prompt --application/shared_components/user_interface/templates/region/spotlight_frame
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(508154034116361921)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TSpotlightFrame #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <span class="amc-TSpotlightFrame-light" aria-hidden="true"></span>',
'  <header class="amc-TSpotlightFrame-header">',
'    <span class="amc-TSpotlightFrame-grid" aria-hidden="true"></span>',
'    <span class="amc-TSpotlightFrame-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'    <h2 class="amc-TSpotlightFrame-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'    <div class="amc-TSpotlightFrame-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'  </header>',
'  <div class="amc-TSpotlightFrame-body">#BODY##SUB_REGIONS#</div>',
'  <footer class="amc-TSpotlightFrame-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  <span class="amc-TSpotlightFrame-rim" aria-hidden="true"></span>',
'</section>'))
,p_page_plug_template_name=>'AMC Spotlight Frame'
,p_internal_name=>'AMC_TPL_SPOTLIGHT_FRAME'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-spotlight-frame.js'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-spotlight-frame.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template with a pointer spotlight. Title and icon come from the region; Help, Edit, Change, Copy, Delete and Create buttons sit in the header, Previous, Close and Next in the footer. The border lights up where the mouse is, a soft light follows it across the frame, and a faint grid appears inside the light in the header. Keyboard focus moves the light to the focused field. Without JavaScript, on touch screens and under reduced motion the light rests in the top start corner and does not move. Template options change the light color to success or danger, widen the light, swap the header grid for dots, or remove the body padding for edge-to-edge reports. In forced-colors mode the frame becomes a plain system border.'
);
end;
