prompt --application/shared_components/user_interface/templates/list/stacked_deck
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(649509334591197437)
,p_list_template_before_rows=>'<ul class="amc-TStackedDeck #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">'
,p_list_template_after_rows=>'</ul>'
,p_list_template_current=>'<li class="amc-TStackedDeck-item is-current"><a class="amc-TStackedDeck-card" href="#LINK#" aria-current="page"><span class="amc-TStackedDeck-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TStackedDeck-text"><span class="amc-TStackedDeck-label">#TEXT#</span><span class="amc-TStackedDeck-desc">#A01#</span></span><span class="amc-TStackedDeck-meta">#A02#</span><span class="amc-TStackedDeck-chevron" aria-hidden="true"></span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TStackedDeck-item"><a class="amc-TStackedDeck-card" href="#LINK#"><span class="amc-TStackedDeck-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TStackedDeck-text"><span class="amc-TStackedDeck-label">#TEXT#</span><span class="amc-TStackedDeck-desc">#A01#</span></span><span class="amc-TStackedDeck-meta">#A02#</span><span class="amc-TStackedDeck-chevron" aria-hidden="true"></span></a></li>'
,p_list_template_name=>'AMC Stacked Deck'
,p_internal_name=>'AMC_TPL_STACKED_DECK'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-stacked-deck.css'
,p_a01_label=>'Description'
,p_a02_label=>'Meta'
,p_list_template_comment=>'List template that shows the entries as a stack of cards. At rest the first entry is in front and up to three more peek out behind it, smaller and shaded; hovering the deck or tabbing into it fans the cards out into a full list, so every link is reachable by mouse and keyboard. On touch screens the deck is always fanned out. Use the Description attribute (A01) for a one-line summary and the Meta attribute (A02) for a short value such as a count or amount shown as a chip. Template options: Always open keeps the list fanned out (no layout change on hover), Tilted deck lays the stack back in 3D, Compact reduces card height, and Solid current fills the current entry with the primary color. Under reduced motion the deck opens and closes without animation; in forced-colors mode cards get system borders.'
);
end;
/
